.md-editor-checkbox {
  cursor: pointer;
  width: 12px;
  height: 12px;
  border: 1px solid var(--md-border-color);
  background-color: var(--md-bk-color-outstand);
  border-radius: 2px;
  line-height: 1;
  text-align: center;
}
.md-editor-checkbox::after {
  content: "";
  font-weight: bold;
}
.md-editor-checkbox-checked::after {
  content: "✓";
}
.md-editor-divider {
  position: relative;
  display: inline-block;
  width: 1px;
  inset-block-start: 0.1em;
  height: 0.9em;
  margin-block: 0;
  margin-inline: 8px;
  background-color: var(--md-border-color);
}
.md-editor-dropdown {
  overflow: hidden;
  box-sizing: border-box;
  position: absolute;
  transition: all 0.3s;
  opacity: 1;
  z-index: 20000;
  background-color: var(--md-bk-color);
}
.md-editor-dropdown-hidden {
  opacity: 0;
  visibility: hidden;
}
.md-editor-dropdown-overlay {
  margin-block-start: 6px;
}
.md-editor-modal-mask {
  position: fixed;
  inset-block-start: 0;
  inset-inline-end: 0;
  inset-block-end: 0;
  inset-inline-start: 0;
  z-index: 20000;
  height: 100%;
  background-color: var(--md-modal-mask);
}
.md-editor-modal {
  display: block;
  background-color: var(--md-bk-color);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";
  border-radius: 3px;
  border: 1px solid var(--md-border-color);
  position: fixed;
  z-index: 20001;
  box-shadow: var(--md-modal-shadow);
}
.md-editor-modal-header {
  cursor: grab;
  display: flex;
  justify-content: space-between;
  padding-block: 10px;
  padding-inline: 24px;
  color: var(--md-color);
  font-weight: 600;
  font-size: 16px;
  line-height: 22px;
  word-wrap: break-word;
  user-select: none;
  border-block-end: 1px solid var(--md-border-color);
  position: relative;
}
.md-editor-modal-body {
  padding-block: 20px;
  padding-inline: 20px;
  font-size: 14px;
  word-wrap: break-word;
  height: calc(100% - 43px);
  box-sizing: border-box;
}
.md-editor-modal .md-editor-modal-func {
  position: absolute;
  inset-block-start: 10px;
  inset-inline-end: 10px;
}
.md-editor-modal .md-editor-modal-func .md-editor-modal-adjust,
.md-editor-modal .md-editor-modal-func .md-editor-modal-close {
  cursor: pointer;
  width: 24px;
  height: 24px;
  line-height: 24px;
  text-align: center;
  display: inline-block;
}
.md-editor-modal .md-editor-modal-func .md-editor-modal-adjust {
  padding-inline-end: 10px;
}
.animation {
  animation-duration: 0.15s;
  animation-fill-mode: forwards;
}
@keyframes zoomIn {
  from {
    opacity: 0;
    transform: scale3d(0.3, 0.3, 0.3);
  }
  50% {
    opacity: 1;
  }
}
.zoom-in {
  animation-name: zoomIn;
  animation-duration: 0.15s;
  animation-fill-mode: forwards;
}
@keyframes zoomOut {
  from {
    opacity: 1;
  }
  50% {
    opacity: 0;
    transform: scale3d(0.3, 0.3, 0.3);
  }
  to {
    opacity: 0;
  }
}
.zoom-out {
  animation-name: zoomOut;
  animation-duration: 0.15s;
  animation-fill-mode: forwards;
}
.md-editor-custom-scrollbar {
