.t-layout {
  font: var(--td-font-body-medium);
  color: var(--td-text-color-primary);
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  list-style: none;
}
.t-layout,
.t-layout__direction-vertical {
  display: flex;
  flex-direction: column;
  background: var(--td-bg-color-page);
  flex: auto;
}
.t-layout--with-sider,
.t-layout__direction-horizontal {
  flex-direction: row;
}
.t-layout__header {
  height: var(--td-comp-size-xxxl);
  background-color: var(--td-bg-color-container);
}
.t-layout__content {
  flex: auto;
}
.t-layout__sider {
  position: relative;
  transition: all 0.2s;
  background: var(--td-bg-color-container);
  width: 232px;
}
.t-layout__footer {
  color: var(--td-text-color-placeholder);
  padding: 24px;
}
.t-divider {
  margin: 0;
  padding: 0;
  list-style: none;
  font: var(--td-font-body-medium);
  margin: var(--td-comp-margin-xxl) 0;
  border-top: 1px solid var(--td-border-level-1-color);
  color: var(--td-text-color-primary);
  box-sizing: border-box;
}
.t-divider--dashed {
  border-top-style: dashed;
}
.t-divider--horizontal {
  width: 100%;
  display: flex;
}
.t-divider--vertical {
  border-top: 0;
  display: inline-block;
  margin: 0 var(--td-comp-margin-m);
  border-left: 1px solid var(--td-border-level-1-color);
  height: 0.9em;
  vertical-align: middle;
}
.t-divider--with-text {
  display: flex;
  border-top: 0;
  white-space: nowrap;
  align-items: center;
}
.t-divider--with-text .t-divider__inner-text:not(:empty) {
  padding: 0 1em;
  display: inline-block;
}
.t-divider--with-text::before,
.t-divider--with-text::after {
  content: '';
  width: 50%;
  border-top: 1px solid var(--td-border-level-1-color);
}
.t-divider--with-text-left::before {
  width: 5%;
}
.t-divider--with-text-left::after {
  width: 95%;
}
.t-divider--with-text-right::before {
  width: 95%;
}
.t-divider--with-text-right::after {
  width: 5%;
}
.t-divider--dashed::before,
.t-divider--dashed::after {
  border-top: 1px dashed var(--td-border-level-1-color);
}
.t-divider--vertical.t-divider--dashed {
  border-left: 1px dashed var(--td-border-level-1-color);
}
.t-space {
  display: inline-flex;
}
.t-space .t-space-item {
  width: inherit;
}
.t-space-align-start {
  align-items: flex-start;
}
.t-space-align-end {
  align-items: flex-end;
}
.t-space-align-baseline {
  align-items: baseline;
}
.t-space-align-center {
  align-items: center;
}
.t-space-vertical {
  flex-direction: column;
}
.t-space-vertical > .t-space-item-separator {
  width: 100%;
}
.t-space.t-space--break-line {
  flex-wrap: wrap;
}
.t-space.t-space--polyfill {
  display: flex;
}
.t-space.t-space--polyfill.t-space-horizontal,
.t-space.t-space--polyfill.t-space--break-line {
  margin-left: calc(-1 * var(--td-space-column-gap, 0));
}
.t-space.t-space--polyfill.t-space-vertical,
.t-space.t-space--polyfill.t-space--break-line {
  margin-top: calc(-1 * var(--td-space-row-gap, 0));
}
.t-space.t-space--polyfill.t-space-horizontal > *,
.t-space.t-space--polyfill.t-space--break-line > * {
  margin-left: var(--td-space-column-gap);
}
.t-space.t-space--polyfill.t-space-vertical > *,
.t-space.t-space--polyfill.t-space--break-line > * {
  margin-top: var(--td-space-row-gap);
}
.t-descriptions {
  font: var(--td-font-body-medium);
  color: var(--td-text-color-primary);
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  list-style: none;
}
.t-descriptions__header {
  color: var(--td-text-color-primary);
  font: var(--td-font-title-medium);
  margin-bottom: var(--td-comp-margin-m);
  font-weight: 600;
}
.t-descriptions__body {
  border-collapse: collapse;
  font: var(--td-font-body-medium);
  width: 100%;
}
.t-descriptions__body.t-size-l > tbody > tr > td {
  padding: var(--td-comp-paddingTB-l) 0;
}
.t-descriptions__body.t-size-m > tbody > tr > td {
  padding: var(--td-comp-paddingTB-m) 0;
}
.t-descriptions__body.t-size-s > tbody > tr > td {
  padding: var(--td-comp-paddingTB-s) 0;
}
.t-descriptions__body .t-descriptions__label {
  color: var(--td-text-color-placeholder);
}
.t-descriptions__body--fixed {
  table-layout: fixed;
}
.t-descriptions__body--border > tbody > tr > td {
  border: 1px solid var(--td-component-border);
}
.t-descriptions__body--border.t-size-l > tbody > tr > td {
  padding: var(--td-comp-paddingTB-l);
}
.t-descriptions__body--border.t-size-m > tbody > tr > td {
  padding: var(--td-comp-paddingLR-m) var(--td-comp-paddingLR-l);
}
.t-descriptions__body--border.t-size-s > tbody > tr > td {
  padding: var(--td-comp-paddingLR-s) var(--td-comp-paddingLR-l);
}
.t-descriptions__body--border .t-descriptions__label {
  background-color: var(--td-bg-color-secondarycontainer);
}
.t-descriptions__body--border .t-descriptions__label:hover {
  background-color: var(--td-bg-color-container-hover);
}
:not(.t-descriptions__body--fixed):not(.t-descriptions__body--border) .t-descriptions__label {
  padding-right: var(--td-comp-paddingLR-l);
}
.t-affix {
  position: fixed;
  z-index: 500;
}
.t-anchor {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  list-style: none;
  --td-anchor-space-base: var(--td-size-6);
  position: relative;
  background: var(--td-bg-color-container);
  width: 200px;
  color: var(--td-text-color-primary);
  font: var(--td-font-body-medium);
}
.t-anchor .t-is-active > a {
  color: var(--td-brand-color);
}
.t-anchor__line {
  position: absolute;
  top: 0;
  left: 0;
  width: 1px;
  height: 100%;
  background-color: var(--td-component-stroke);
  cursor: pointer;
}
.t-anchor__line-cursor-wrapper {
  position: absolute;
  display: block;
  height: 0;
  opacity: 0;
  transition: all 0.2s cubic-bezier(0.24, 0.41, 0.51, 0.9);
}
.t-anchor__line-cursor-wrapper .t-anchor__line-cursor {
  width: 1px;
  height: 100%;
  background-color: var(--td-brand-color);
}
.t-anchor__item {
  padding: var(--td-comp-paddingTB-xxs) var(--td-comp-paddingTB-l);
  --level: 1;
  padding-left: calc(var(--level) * var(--td-anchor-space-base));
  display: flex;
  flex-direction: column;
}
.t-anchor__item.t-is-active {
  font-weight: 500;
}
.t-anchor__item-link {
  display: inline-block;
  position: relative;
  overflow: hidden;
  word-break: break-all;
  color: var(--td-text-color-primary);
  text-decoration: none;
  text-align: justify;
}
.t-anchor a {
  transition: color 0.2s linear;
}
.t-anchor a:hover {
  color: var(--td-brand-color);
  cursor: pointer;
}
.t-anchor a:active {
  color: var(--td-brand-color-active);
}
.t-anchor.t-size-s {
